contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _minSum, uint _depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_depositAmount)); require(_depositAmount <= 1000000000000000000000000000000);
        require(_depositAmount == _minSum);
        require(address(this).balance >= _depositAmount);

        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        uint beforeCallerBal;
        uint beforeContractBal;

        c.Deposit{value: _depositAmount}(); if (__ESBMC_reverted()) return;
        beforeCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        beforeContractBal = address(c).balance;

        bool collectReverted;
        c.Collect(_minSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            collectReverted = true;
        } else {
            collectReverted = false;
        }

        uint afterCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        assert(!collectReverted && afterCallerBal == 0 && beforeContractBal - afterContractBal == _minSum);
    }

    receive() external payable {}
}

