pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _minSum, uint256 _depositAmount) internal {
        _depositAmount = bound(_depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        _depositAmount = _minSum;
        vm.assume(address(this).balance >= _depositAmount);
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint beforeCallerBal;
        uint beforeContractBal;
        try c.Deposit{value: _depositAmount}() {} catch { return; }
        try c.balances(address(this)) returns (uint256 __r) { beforeCallerBal = __r; } catch { return; }
        beforeContractBal = address(c).balance;
        bool collectReverted;
        try c.Collect(_minSum) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }
        uint256 afterCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { afterCallerBal = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(!collectReverted && afterCallerBal == 0 && beforeContractBal - afterContractBal == _minSum);
    }

    function testFuzz_run(uint256 _minSum, uint256 _depositAmount) public {
        _run(_minSum, _depositAmount);
    }

    receive() external payable {}
}
